package studio.solocamera;

import android.content.ContentResolver;
import android.content.Context;
import android.net.Uri;
import org.json.JSONObject;
import java.io.*;
import java.net.*;
import java.util.*;

/** Thin mobile client for the first-party publishing service. Social tokens never enter the APK. */
final class PublishApiClient {
    interface Progress {void update(long sent,long total);}
    static final class Upload {final String id,url;final JSONObject headers;Upload(String id,String url,JSONObject headers){this.id=id;this.url=url;this.headers=headers;}}
    private final Context context;private final String base,token;
    PublishApiClient(Context context,String base,String token){this.context=context.getApplicationContext();this.base=normalize(base);this.token=token==null?"":token;}
    static String normalize(String value){return value==null?"":value.trim().replaceAll("/+$","");}
    boolean configured(){return !base.isEmpty();}
    private HttpURLConnection open(String url)throws IOException{URL parsed=new URL(url);boolean local=parsed.getHost().equals("localhost")||parsed.getHost().equals("127.0.0.1")||parsed.getHost().equals("10.0.2.2");if(!parsed.getProtocol().equals("https")&&!(local&&parsed.getProtocol().equals("http")))throw new IOException("Publishing service must use HTTPS");HttpURLConnection c=(HttpURLConnection)parsed.openConnection();c.setConnectTimeout(15000);c.setReadTimeout(60000);return c;}
    JSONObject request(String method,String path,JSONObject body)throws IOException{return request(method,path,body,false);}
    private JSONObject request(String method,String path,JSONObject body,boolean unauthenticated)throws IOException{HttpURLConnection c=open(base+path);try{c.setRequestMethod(method);c.setRequestProperty("Accept","application/json");if(!unauthenticated&&!token.isEmpty())c.setRequestProperty("Authorization","Bearer "+token);if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json; charset=utf-8");try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes("UTF-8"));}}int status=c.getResponseCode();InputStream stream=status>=400?c.getErrorStream():c.getInputStream();String response=read(stream);if(status<200||status>=300)throw new IOException(errorMessage(response,status));return response.isEmpty()?new JSONObject():new JSONObject(response);}catch(org.json.JSONException e){throw new IOException("Publishing service returned invalid JSON",e);}finally{c.disconnect();}}
    JSONObject health()throws IOException{return request("GET","/v1/health",null);}
    JSONObject accounts()throws IOException{return request("GET","/v1/accounts",null);}
    JSONObject jobs()throws IOException{return request("GET","/v1/publishing/jobs",null);}
    JSONObject connect(String provider,String deviceId)throws IOException{try{if(token.isEmpty())return request("POST","/v1/mobile/oauth/start",new JSONObject().put("provider",provider).put("deviceId",deviceId),true);return request("POST","/v1/oauth/"+provider+"/start",new JSONObject());}catch(org.json.JSONException e){throw new IOException(e);}}
    JSONObject completeOAuth(String provider,String state,String callbackTicket,String deviceId)throws IOException{try{JSONObject body=new JSONObject().put("provider",provider).put("state",state).put("callbackTicket",callbackTicket).put("deviceId",deviceId);return request("POST","/v1/mobile/oauth/complete",body,token.isEmpty());}catch(org.json.JSONException e){throw new IOException(e);}}
    Upload beginUpload(String name,String mime,long bytes)throws IOException{try{JSONObject response=request("POST","/v1/uploads",new JSONObject().put("fileName",name).put("contentType",mime).put("sizeBytes",bytes));return new Upload(response.getString("uploadId"),response.getString("uploadUrl"),response.optJSONObject("headers")==null?new JSONObject():response.getJSONObject("headers"));}catch(org.json.JSONException e){throw new IOException("Could not initialize media upload",e);}}
    JSONObject completeUpload(String uploadId)throws IOException{return request("POST","/v1/uploads/"+URLEncoder.encode(uploadId,"UTF-8")+"/complete",new JSONObject());}
    void upload(Upload upload,Uri uri,String mime,Progress progress)throws IOException{URL uploadUrl=new URL(upload.url);if(!"https".equalsIgnoreCase(uploadUrl.getProtocol()))throw new IOException("The signed upload URL must use HTTPS");ContentResolver resolver=context.getContentResolver();long total=0;try{android.database.Cursor cursor=resolver.query(uri,new String[]{"_size"},null,null,null);if(cursor!=null){try{if(cursor.moveToFirst())total=cursor.getLong(0);}finally{cursor.close();}}}catch(Exception ignored){}HttpURLConnection connection=(HttpURLConnection)uploadUrl.openConnection();connection.setConnectTimeout(15000);connection.setReadTimeout(120000);connection.setRequestMethod("PUT");connection.setDoOutput(true);connection.setRequestProperty("Content-Type",mime);if(total>0)connection.setFixedLengthStreamingMode(total);Iterator<String> names=upload.headers.keys();while(names.hasNext()){String key=names.next();connection.setRequestProperty(key,upload.headers.optString(key));}try(InputStream in=resolver.openInputStream(uri);OutputStream out=connection.getOutputStream()){if(in==null)throw new IOException("Cannot read selected video. Re-select it from the media picker.");byte[] buffer=new byte[256*1024];long sent=0;int n;while((n=in.read(buffer))!=-1){out.write(buffer,0,n);sent+=n;if(progress!=null)progress.update(sent,total);}}try{int status=connection.getResponseCode();String body=read(status>=400?connection.getErrorStream():connection.getInputStream());if(status<200||status>=300)throw new IOException(errorMessage(body,status));}finally{connection.disconnect();}}
    JSONObject createJob(String uploadId,PublishDraftStore.Draft draft,String timezone)throws IOException{try{JSONObject channels=new JSONObject();for(String platform:draft.platforms){JSONObject options=draft.channelOptions.optJSONObject(platform);JSONObject channel=options==null?new JSONObject():new JSONObject(options.toString());channel.put("caption",draft.caption);channels.put(platform,channel);}JSONObject body=new JSONObject().put("uploadId",uploadId).put("channels",channels).put("scheduledAt",draft.scheduledAt==0?JSONObject.NULL:draft.scheduledAt).put("timeZone",timezone).put("idempotencyKey",draft.id);return request("POST","/v1/publishing/jobs",body);}catch(org.json.JSONException e){throw new IOException("Could not prepare publishing job",e);}}
    private static String read(InputStream in)throws IOException{if(in==null)return"";try(BufferedReader reader=new BufferedReader(new InputStreamReader(in,"UTF-8"))){StringBuilder out=new StringBuilder();String line;while((line=reader.readLine())!=null){if(out.length()>500_000)throw new IOException("Publishing response is too large");out.append(line);}return out.toString();}}
    private static String errorMessage(String body,int status){try{JSONObject j=new JSONObject(body);return j.optString("message",j.optString("error","Publishing service error ("+status+")"));}catch(Exception ignored){return"Publishing service error ("+status+")";}}
}
